<template>
    <div class="app-main__inner">
        <!--Titulo página-->
        <PageTitle title="Clientes" icon="pe-7s-users" subtitle=""/>     
        <!--Fin titulo página-->
        <!--Contenido-->
        <div class="row">
            <div class="col-md-12 col-lg-12">
                <div class="main-card mb-3 card">
                    <div class="card-body"><h5 class="card-title">Editar cliente</h5>
                        <div class="alert alert-danger fade show" role="alert" v-if="errors">
                            <li v-for="(error, index) in errors" :key="'errors-' + index">{{ error[0] }}</li>
                        </div>
                        <form @submit.prevent="save">
                            <div class="row">
                                <div class="col-md-4">
                                    <div class="position-relative form-group">
                                        <label for="" class="">Identificación (*)</label>
                                        <input type="text" class="form-control" v-model="client.identification" maxlength="20">
                                    </div>
                                </div>
                                <div class="col-md-4">
                                    <div class="position-relative form-group">
                                        <label for="" class="">Nombres (*)</label>
                                        <input type="text" class="form-control" v-model="client.names" maxlength="50">
                                    </div>
                                </div>
                                <div class="col-md-4">
                                    <div class="position-relative form-group">
                                        <label for="" class="">Apellidos (*)</label>
                                        <input type="text" class="form-control" v-model="client.lastname" maxlength="50">
                                    </div>
                                </div>
                            </div>
                            <div class="row">
                                <div class="col-md-4">
                                    <div class="position-relative form-group">
                                        <label for="" class="">Sexo (*)</label>
                                        <select class="form-control" v-model="client.sex">
                                            <option value="">Seleccione opción</option>
                                            <option value="Masculino">Masculino</option>
                                            <option value="Femenino">Femenino</option>
                                        </select>
                                    </div>
                                </div>
                                <div class="col-md-4">
                                    <div class="position-relative form-group">
                                        <label for="" class="">Fecha de nacimiento (*)</label>
                                        <input type="date" class="form-control" v-model="client.date_of_birth">
                                    </div>
                                </div>
                                <div class="col-md-4">
                                    <div class="position-relative form-group">
                                        <label for="" class="">Dirección</label>
                                        <input type="text" class="form-control" v-model="client.address" maxlength="80">
                                    </div>
                                </div>
                                <div class="col-md-4">
                                    <div class="position-relative form-group">
                                        <label for="" class="">Email</label>
                                        <input type="email" class="form-control" v-model="client.email" maxlength="80">
                                    </div>
                                </div>
                                <div class="col-md-8">
                                    <div class="position-relative form-group">
                                        <label for="" class="">Teléfono</label>
                                        <input type="number" class="form-control" v-model="client.phonenumber" maxlength="20">
                                    </div>
                                </div>
                            </div>
                            <div class="row">
                                <div class="col-md-4">
                                    <div class="position-relative form-group">
                                        <label for="" class="">Foto</label>
                                        <croppa v-model="myCroppa" 
                                                placeholder="Seleccione imagen"
                                                :placeholder-font-size="14"
                                                :prevent-white-space="true"></croppa>
                                        
                                    </div>
                                </div>
                            </div>
                            <a href="#" :class="{'mt-1 btn btn-secondary mr-1': true, disabled: saving}" @click.prevent="$router.push({ name: 'clients.index' })">
                                <i class="fa fa-undo"></i> Atrás
                            </a>
                            <button class="mt-1 btn btn-primary" :disabled="saving">
                                <div class="spinner-border spinner-border-sm" role="status" v-if="saving">
                                    <span class="sr-only">Loading...</span>
                                </div>
                                <i class="fa fa-save" v-else></i> Guardar
                            </button>
                        </form>
                    </div>
                </div>
            </div>
        </div>
        <!--Fin contenido-->
    </div>
</template>
<script>
import PageTitle from '../components/PageTitle.vue'
export default {
    components: { PageTitle },
    created () {
        this.getClient()
    },
    data () {
        return {
            client: {
                identification: '',
                names: '',
                lastname: '',
                sex: '',
                date_of_birth: '',
                address: '',
                email: '',
                phonenumber: '',
            },
            myCroppa: {},
            errors: null,
            saving: false
        }
    },
    methods: {
        getClient () {
            this.$http.get(`clients/${ this.$route.params.id }/edit`).then( response => {
                this.client.identification = response.data.identification
                this.client.names = response.data.names
                this.client.lastname = response.data.lastname
                this.client.sex = response.data.sex
                this.client.date_of_birth = response.data.date_of_birth
                this.client.address = response.data.address ? response.data.address : ''
                this.client.email = response.data.email ? response.data.email : ''
                this.client.phonenumber = response.data.phonenumber ? response.data.phonenumber : ''
            })
        },
        save () {
            this.myCroppa.generateBlob(blob => {
                this.saving = true

                let data = new FormData()

                data.append('photo', blob)
                data.append('identification', this.client.identification)
                data.append('names', this.client.names)
                data.append('lastname', this.client.lastname)
                data.append('sex', this.client.sex)
                data.append('date_of_birth', this.client.date_of_birth)
                data.append('address', this.client.address)
                data.append('email', this.client.email)
                data.append('phonenumber', this.client.phonenumber)
                data.append('_method', 'put')

                this.$http.post(`clients/${ this.$route.params.id }`, data).then( response => {
                    this.$toastr.success('Cliente actualizado')
                    this.$router.push({ name: 'clients.index' })
                }).catch( error => {
                    this.saving = false
                    if (error.response.status == 422) {
                        this.$toastr.error('Verifica los errores de validación')
                        this.errors = error.response.data.errors
                    }
                })
            })

        },
    }
}
</script>